select *
from DIS_PROD_FEEDISCOUNT
where PROD_ID = #{prodId,jdbcType=VARCHAR}
    and PROD_REGIST_NO = #{prodRegistNo,jdbcType=VARCHAR}
    and RPT_ISSUE_DATE = #{rptIssueDate,jdbcType=DATE}
    and FEENAME = #{feename,jdbcType=VARCHAR}
    and DATA_STATUS = 'E'

    and START_DATE = #{startDate,jdbcType=DATE}


    and END_DATE = #{endDate,jdbcType=DATE}


    and IS_SALES_AGENCY = #{isSalesAgency,jdbcType=VARCHAR}


    and IS_SALES_AGENCY is null


    and PROD_DIS_REMARK = #{prodDisRemark,jdbcType=VARCHAR}


    and PROD_DIS_REMARK is null


    and PRE_FEERATE = #{preFeerate,jdbcType=VARCHAR}


    and PRE_FEERATE is null


    and AFTER_FEERATE = #{afterFeerate,jdbcType=VARCHAR}


    and AFTER_FEERATE is null


    and THIS_PRE_FEERATE = #{thisPreFeerate,jdbcType=DECIMAL}


    and THIS_PRE_FEERATE is null


    and THIS_AFTER_FEERATE = #{thisAfterFeerate,jdbcType=DECIMAL}


    and THIS_AFTER_FEERATE is null


    and THIS_END_FEERATE = #{thisEndFeerate,jdbcType=DECIMAL}


    and THIS_END_FEERATE is null


    and FEE_DIS_REMARK = #{feeDisRemark,jdbcType=VARCHAR}


    and FEE_DIS_REMARK is null
